  await say(MY,'red_was_it_strangled',{to:BU});await say(BU,'butcher_bled_clean_but_the_temple',{to:MY});await say(MY,'red_not_from_the_temple_not_anymore',{to:BU});
  await say(BU,'butcher_as_you_like',{to:MY});
